/**
 * One analysis in, three charts out.
 *
 * The workflow this module implements is the phase 3 brief verbatim:
 *
 *     1. import audio
 *     2. decode and analyse it **once**
 *     3. build one shared musical event timeline (the `AnalysisResult`)
 *     4. generate Easy, Normal and Hard **independently** from that timeline
 *     5. keep all three charts with the song
 *     6. switch difficulty without re-analysing anything
 *
 * Point 4 is the one that is easy to get wrong. Each difficulty is generated by a full run of the
 * chart generator with its own lane count, its own lane profile and its own density/chord/hold
 * budgets; nothing is copied from Hard and no lanes are hidden. A consequence worth stating plainly:
 * **the three charts do not share a note list.** Easy is a different selection of the same events,
 * which is exactly what makes it playable.
 *
 * Determinism. A chart set is a pure function of `(analysis, seed, generator version)`. Each
 * difficulty draws from a seed derived from the base seed *and its own name*, so the three charts
 * are independent but reproducible, and changing the seed for one difficulty does not reshuffle the
 * others — with one deliberate exception: **Hard uses the base seed itself** (`seedForDifficulty`),
 * because that is the seed the phase 2.x generator used for the seven-key chart. Deriving a new one
 * for Hard would quietly replace every seven-key chart with a differently shaped one, which is the
 * regression phase 3.1 fixes.
 *
 * What each chart carries (the brief lists these): difficulty id, lane count, key mapping, notes,
 * duration, BPM metadata, generator name/version/seed, estimated note density and the theoretical
 * maximum score (`Beatmap.maxScore`, from `chart/ScoreModel`).
 */

import type { AnalysisSummary } from '../analysis/types';
import { GENERATOR_NAME, GENERATOR_VERSION, generateChart, type ChartStats } from './ChartGenerator';
import { validateBeatmap, type ValidationResult } from './ChartValidator';
import type { Beatmap } from './ChartTypes';
import { lanesOf } from './ChartTypes';
import {
  CHART_DIFFICULTIES,
  DIFFICULTY_PROFILES,
  isChartDifficulty,
  difficultyProfile,
  type ChartDifficulty,
  type DifficultyProfile,
} from './Difficulty';
import { maxTheoreticalScoreOf } from './ScoreModel';

/** Version of the *set* generator (the per-chart generator has its own version). */
export const CHART_SET_VERSION = '3.1.0';

export interface DifficultyChart {
  difficulty: ChartDifficulty;
  profile: DifficultyProfile;
  chart: Beatmap;
  stats: ChartStats;
  validation: ValidationResult;
  warnings: string[];
}

/** Charts by difficulty. Partial on purpose: a legacy song may only have Hard. */
export type DifficultyCharts = Partial<Record<ChartDifficulty, DifficultyChart>>;

export interface ChartSet {
  songId: string;
  title: string;
  artist?: string;
  charter?: string;
  /** Authoritative duration source is still the decoded audio; this is the generator's hint. */
  durationMs: number;
  bpm: number;
  generator: { name: string; version: string; seed: number };
  charts: DifficultyCharts;
  /** Non-fatal problems, per difficulty plus the set itself. */
  warnings: string[];
}

export interface GenerateChartSetOptions {
  seed: number;
  songId: string;
  title: string;
  artist?: string;
  charter?: string;
  durationMs?: number;
  /** Which difficulties to build. Defaults to all three. */
  difficulties?: readonly ChartDifficulty[];
}

/**
 * Generate the chart set for one analysis.
 *
 * Every difficulty runs the real generator, so a difficulty that ends up unplayable (a three-second
 * clip has no room for a four-lane chart either) reports its own validation result rather than
 * being silently dropped — the caller decides what to do with it.
 */
export function generateChartSet(analysis: AnalysisSummary, options: GenerateChartSetOptions): ChartSet {
  const requested = options.difficulties ?? CHART_DIFFICULTIES;
  const charts: DifficultyCharts = {};
  const warnings: string[] = [];

  for (const difficulty of requested) {
    const profile = difficultyProfile(difficulty);
    const generated = generateChart(analysis, {
      ...profile.generation,
      seed: seedForDifficulty(options.seed, difficulty),
      songId: options.songId,
      title: options.title,
      ...(options.artist ? { artist: options.artist } : {}),
      ...(options.charter ? { charter: options.charter } : {}),
      durationMs: options.durationMs ?? analysis.durationMs,
      laneCount: profile.laneCount,
      difficulty: profile.id,
      difficultyWeight: profile.scoreWeight,
    });
    const validation = validateBeatmap(generated.chart);
    charts[difficulty] = {
      difficulty,
      profile,
      chart: generated.chart,
      stats: generated.stats,
      validation,
      warnings: generated.warnings,
    };
    for (const warning of generated.warnings) warnings.push(`${difficulty}: ${warning}`);
    if (!validation.ok) {
      warnings.push(
        `${difficulty}: chart failed validation (${validation.errors.map((error) => error.code).join(', ')})`,
      );
    }
  }

  return {
    songId: options.songId,
    title: options.title,
    ...(options.artist ? { artist: options.artist } : {}),
    ...(options.charter ? { charter: options.charter } : {}),
    durationMs: options.durationMs ?? analysis.durationMs,
    bpm: analysis.bpm,
    generator: { name: GENERATOR_NAME, version: GENERATOR_VERSION, seed: options.seed },
    charts,
    warnings,
  };
}

/**
 * A set that holds a single, already-built chart.
 *
 * Two callers need this: the hand-authored demo chart (one fixed seven-lane map, no analysis), and
 * the migration path for a song saved before phase 3 (a seven-key chart, which is Hard by
 * definition — see `storage/SongRecord.ts`). The other difficulties are then *absent*, not faked:
 * the picker shows them as unavailable and the library offers to regenerate them from the stored
 * audio, which is the honest alternative to inventing two charts from numbers that are not there.
 */
export function chartSetFromCharts(input: {
  songId: string;
  title: string;
  artist?: string;
  charter?: string;
  durationMs: number;
  bpm: number;
  generator: { name: string; version: string; seed: number };
  charts: readonly DifficultyChart[];
  warnings?: readonly string[];
}): ChartSet {
  const charts: DifficultyCharts = {};
  for (const entry of input.charts) charts[entry.difficulty] = entry;
  return {
    songId: input.songId,
    title: input.title,
    ...(input.artist ? { artist: input.artist } : {}),
    ...(input.charter ? { charter: input.charter } : {}),
    durationMs: input.durationMs,
    bpm: input.bpm,
    generator: { ...input.generator },
    charts,
    warnings: [...(input.warnings ?? [])],
  };
}

/** Difficulties present in a set, in the canonical easy → hard order. */
export function availableDifficulties(set: ChartSet): ChartDifficulty[] {
  return CHART_DIFFICULTIES.filter((difficulty) => set.charts[difficulty] !== undefined);
}

/**
 * The difficulty a set opens on when nothing else is known: Hard when it exists (the full seven-key
 * chart is the "real" one), otherwise the hardest available.
 */
export function defaultDifficultyOf(set: ChartSet): ChartDifficulty | null {
  const available = availableDifficulties(set);
  if (available.length === 0) return null;
  for (const preferred of ['hard', 'normal', 'easy'] as const) {
    if (available.includes(preferred)) return preferred;
  }
  return available[available.length - 1]!;
}

export function chartInSet(set: ChartSet, difficulty: ChartDifficulty): Beatmap | null {
  return set.charts[difficulty]?.chart ?? null;
}

/** The chart a set opens on, with the difficulty it belongs to. */
export function primaryChart(set: ChartSet, preference?: ChartDifficulty): { difficulty: ChartDifficulty; chart: Beatmap } | null {
  const wanted = preference ?? defaultDifficultyOf(set);
  if (wanted === null) return null;
  const chart = chartInSet(set, wanted);
  if (chart !== null) return { difficulty: wanted, chart };
  const fallback = defaultDifficultyOf(set);
  if (fallback === null) return null;
  const fallbackChart = chartInSet(set, fallback);
  return fallbackChart === null ? null : { difficulty: fallback, chart: fallbackChart };
}

export function difficultySummary(set: ChartSet, difficulty: ChartDifficulty): {
  profile: DifficultyProfile;
  laneCount: number;
  noteCount: number;
  notesPerSecond: number;
  maxScore: number;
  scoreWeight: number;
  valid: boolean;
} | null {
  const entry = set.charts[difficulty];
  if (!entry) return null;
  return {
    profile: entry.profile,
    laneCount: lanesOf(entry.chart),
    noteCount: entry.stats.noteCount,
    notesPerSecond: entry.stats.notesPerSecond,
    maxScore: entry.chart.maxScore ?? maxTheoreticalScoreOf(entry.chart.notes, entry.profile.scoreWeight),
    scoreWeight: entry.profile.scoreWeight,
    valid: entry.validation.ok,
  };
}

/**
 * The seed a difficulty's chart is generated from.
 *
 * Easy and Normal hash the base seed with the difficulty name (`deriveDifficultySeed`), so they are
 * independent of each other and of Hard. **Hard uses the base seed unchanged**, which is what makes
 * its seven-key chart reproduce the phase 2.x one for the same song and seed.
 */
export function seedForDifficulty(seed: number, difficulty: ChartDifficulty): number {
  if (difficulty === 'hard') {
    const base = Math.trunc(seed);
    return Number.isFinite(base) && base !== 0 ? base : 1;
  }
  return deriveDifficultySeed(seed, difficulty);
}

/**
 * Seed for one difficulty inside a set. A small string hash of `seed:difficulty` — deterministic,
 * cheap, and unrelated to `seededRandom` so a difficulty's seed cannot be guessed from another's.
 */
export function deriveDifficultySeed(seed: number, difficulty: ChartDifficulty): number {
  const source = `${Math.trunc(seed) || 1}:${difficulty}`;
  let hash = 2166136261;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) || 1;
}

/** True when a value is a chart set this build understands. Used by the storage layer. */
export function isChartSet(value: unknown): value is ChartSet {
  if (typeof value !== 'object' || value === null) return false;
  const set = value as Partial<ChartSet>;
  if (typeof set.songId !== 'string' || typeof set.title !== 'string') return false;
  if (typeof set.charts !== 'object' || set.charts === null) return false;
  return Object.keys(set.charts).some((key) => isChartDifficulty(key));
}

/** The lane count and key labels of a chart, with the pre-phase-3 default (seven lanes). */
export function laneInfoOf(chart: Beatmap): { laneCount: number; keyLabels: string[] | null } {
  return { laneCount: lanesOf(chart), keyLabels: chart.keyLabels ?? null };
}

export { DIFFICULTY_PROFILES };
